retrieval.cypher:
MATCH (a:PlantItem {tag: 'P-35801'}), (b:PlantItem {tag: 'D-35801'})
CALL {
  WITH a
  MATCH (a)-[:line_to*1..]->(v:Valve)
  RETURN collect(DISTINCT v.tag) AS downstreamTags
}
CALL {
  WITH b
  MATCH (v:Valve)-[:line_to*1..]->(b)
  RETURN collect(DISTINCT v.tag) AS upstreamTags
}
WITH [tag IN downstreamTags WHERE tag IN upstreamTags] AS valveTags
RETURN size(valveTags) AS valve_count, valveTags AS valve_tags

